def merge_intervals(xs):
    if not xs:
        return []
    xs.sort(key=lambda x: x[0])
    merged = [xs[0]]
    for start, end in xs[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))
    return merged
```

